/// Returns the monetary loss given a cost price and a selling price.
///
/// Loss is (cost_price - selling_price) if cost_price > selling_price,
/// otherwise loss is 0.
///
/// Assumes inputs are non-negative.
pub fn calculate_loss(cost_price: i32, selling_price: i32) -> i32 {
    if cost_price > selling_price {
        cost_price - selling_price
    } else {
        0
    }
}

